1	// CSV export: serializes #report-table to a downloadable CSV file.
2	document.getElementById("export-csv").addEventListener("click", () => {
3	  const rows = [...document.querySelectorAll("#report-table tr")];
4	  const csv = rows.map(r => [...r.cells].map(c => c.textContent).join(",")).join("\n");
5	  const a = document.createElement("a");
6	  a.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
7	  a.download = "report.csv";
8	  a.click();
9	});
